#!/usr/bin/env bash
set -e

cat > CHANGELOG.md <<'EOF'
# Changelog

## Unreleased
- feat(auth): add OAuth login support

## 1.0.0 - 2024-01-01
- Initial release
EOF

mkdir -p src/cli
cat > src/cli/flags.js <<'EOF'
function parseFlags(argv) {
  const verbose = argv.includes('--verbose');
  const quiet = argv.includes('--quiet');
  if (quiet) {
    // --quiet silently wins; --verbose is dropped with no warning.
    return { verbose: false, quiet: true };
  }
  return { verbose, quiet };
}

module.exports = { parseFlags };
EOF

